class Solution {
  findLengthOfLoop(head) {
    let temp = head;
    const map = new Map();
    let index = 0;
    while (temp !== null) {
      if (map.has(temp)) {
        let loopIdx = map.get(temp);
        return index - loopIdx;
      }
      map.set(temp, index);
      temp = temp.next;
      index++;
    }
    return 0;
  }
}

